async function api(path,options={}) {
  const res=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json','X-Gestor-Request':'1',...options.headers}});
  const data=await res.json();if(!res.ok){if(res.status===401&&path!=='/login'){state=null;login();}const error=new Error(data.error||'Não foi possível concluir.');error.suggestions=data.suggestions||[];throw error;}return data;
}
const post=(path,data)=>api(path,{method:'POST',body:JSON.stringify(data)});
function toast(message,error=false){$('#toast').textContent=message;$('#toast').className=error?'visible error':'visible';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').className='',5000);}
function options(values,current){return Object.entries(values).map(([v,label])=>`<option value="${h(v)}" ${v===current?'selected':''}>${h(label)}</option>`).join('');}
function providerOptions(selected){return state.providers.filter(p=>p.active).map(p=>`<option value="${h(p.id)}" ${p.id===selected?'selected':''}>${h(p.name)} · ${h(p.specialty)}</option>`).join('');}
function propOptions(selected){return state.properties.map(p=>{const address=p.property_street?[p.property_street,p.property_number,p.property_neighborhood,p.property_city,p.property_complement].filter(Boolean).join(' · '):`${p.name} · ${p.unit}`;return `<option value="${h(p.id)}" ${p.id===selected?'selected':''}>${h(p.code)} · ${h(address)}</option>`;}).join('');}
function initials(name){return name.split(' ').slice(0,2).map(n=>n[0]).join('');}
function empty(title,body,button=''){return `<div class="empty">${icon('leaf')}<h3>${h(title)}</h3><p>${h(body)}</p>${button}</div>`;}
function login(){
  $('#app').innerHTML=`<main class="login"><section class="login-story"><a class="brand" href="#overview"><img src="/favicon.svg" alt=""><span>gestor<span class="brand-light">imob</span><small>VISTORIAS E CONTRATOS</small></span></a><div><span class="eyebrow">MENOS RUÍDO. MAIS CUIDADO.</span><h1>Cada imóvel tem uma história.<br>Cuide de cada detalhe.</h1><p>Vistorias, contratos e próximos passos<br>em um só lugar.</p><div class="login-illustration" aria-hidden="true"><div class="building-art one"><i></i><i></i><i></i><i></i></div><div class="building-art two"><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="plant-art">${icon('leaf')}</div><div class="art-label">${icon('check')} Tudo no seu lugar</div></div></div><span class="login-foot">Sistema desenvolvido e criado por Léo Antunes</span></section><section class="login-form"><div class="login-card"><div class="login-card-top"><span class="demo-tag">Acesso da equipe</span>${themeButton()}</div><h2>Bom ter você por aqui.</h2><p>Entre para acompanhar sua operação.</p><form data-form="login"><label>Usuário ou e-mail<input name="identifier" type="text" autocomplete="username" placeholder="Seu usuário ou e-mail" required></label><label>Senha<input name="password" type="password" autocomplete="current-password" placeholder="Sua senha" required></label><p class="form-error" role="alert"></p><button class="btn primary full" type="submit">Entrar no painel ${icon('arrow')}</button></form><p class="demo-note">Use o usuário ou e-mail e a senha cadastrados pela Gestão.</p></div></section></main>`;
}
function shell(){
  if(!pages[page])page='inspections';
  if(page==='contracts'&&!canUseContracts())page='inspections';
  const [title,subtitle]=pages[page];
  $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a href="#overview" class="brand" data-nav="overview"><img src="/favicon.svg" alt=""><span>gestor<span class="brand-light">imob</span><small>VISTORIAS E CONTRATOS</small></span></a><span class="nav-label">GESTÃO</span><nav aria-label="Navegação principal">${[['overview','grid','Visão geral'],['tickets','ticket','Chamados'],['properties','building','Imóveis'],...(!canManage()?[['providers','tool','Prestadores']]:[]),['agenda','calendar','Agenda'],['notifications','alert','Avisos'],['reports','chart','Relatórios']].map(([key,i,label])=>`<a href="#${key}" data-nav="${key}" class="nav-item ${page===key?'selected':''}" ${page===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${key==='tickets'?`<b>${state.tickets.filter(active).length}</b>`:key==='notifications'&&state.notifications?.unread_count?`<b>${state.notifications.unread_count}</b>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="user-card"><span class="avatar">${h(initials(state.user.name))}</span><div><strong>${h(state.user.name)}</strong><small>${{admin:'Gestão',staff:'Atendimento',finance:'Financeiro'}[state.user.role]}</small></div><button class="icon-btn" data-action="logout" aria-label="Sair">${icon('logout')}</button></div></div></aside><div class="workspace-main"><header class="topbar"><div class="breadcrumb">Painel <span>/</span> <strong>${title}</strong></div><div class="topbar-right">${themeButton()}<span class="topbar-date">${new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',timeZone:'America/Sao_Paulo'}).format(new Date())}</span><span class="avatar small">${h(initials(state.user.name))}</span><button class="icon-btn mobile-logout" data-action="logout" aria-label="Sair da conta">${icon('logout')}</button></div></header><main id="main"><div class="page-heading"><div><p class="eyebrow">${page==='overview'?'SEU DIA, ORGANIZADO':'GESTOR IMOB'}</p><h1>${page==='overview'?'Tudo sob controle.':title}</h1><p>${page==='overview'?'Acompanhe sua carteira e cuide do que precisa de atenção.':subtitle}</p></div><div class="heading-actions">${page==='reports'?`<a class="btn secondary" href="/api/export">${icon('file')} Exportar CSV</a>`:''}<button class="btn primary" data-action="new-ticket">${icon('plus')} Novo chamado</button></div></div><div id="page-content">${content()}</div><footer class="page-footer"><span>Gestor Imob <span class="footer-dot">·</span> Cuidar fica mais simples.</span><span>Sistema desenvolvido e criado por Léo Antunes</span></footer></main></div></div>`;
  const nav=$('nav[aria-label="Navegação principal"]');
  nav.insertAdjacentHTML('afterbegin',`<a href="#inspections" data-nav="inspections" class="nav-item ${page==='inspections'?'selected':''}" ${page==='inspections'?'aria-current="page"':''}>${icon('building')}<span>Vistorias</span></a>`);
  nav.insertBefore(nav.querySelector('[data-nav="agenda"]'),nav.children[1]);
  if(canUseContracts())nav.querySelector('[data-nav="inspections"]').insertAdjacentHTML('afterend',`<a href="#contracts" data-nav="contracts" class="nav-item ${page==='contracts'?'selected':''}" ${page==='contracts'?'aria-current="page"':''}>${icon('file')}<span>Contratos</span>${state.contracts?.filter(c=>c.overdue).length?`<b>${state.contracts.filter(c=>c.overdue).length}</b>`:''}</a>`);
  if(canManage())nav.insertAdjacentHTML('beforeend',`<span class="nav-label nav-admin-label">ADMINISTRAÇÃO</span><a href="#team" data-nav="team" class="nav-item ${page==='team'?'selected':''}" ${page==='team'?'aria-current="page"':''}>${icon('grid')}<span>Equipe</span></a><a href="#providers" data-nav="providers" class="nav-item ${page==='providers'?'selected':''}" ${page==='providers'?'aria-current="page"':''}>${icon('tool')}<span>Prestadores</span></a>`);
  nav.querySelector('[data-nav="tickets"] span').textContent='Manutenções';
  const brand=$('.sidebar .brand');brand.href='#inspections';brand.dataset.nav='inspections';
  $('.nav-label').textContent='OPERAÇÃO';$('.brand small').textContent='VISTORIAS E GESTÃO IMOBILIÁRIA';
  if(['inspections','agenda'].includes(page)){const button=$('.heading-actions [data-action="new-ticket"]');button.dataset.action='new-inspection';button.innerHTML=`${icon('plus')} Novo pedido`;}
  if(page==='contracts'){const button=$('.heading-actions [data-action="new-ticket"]');if(canManage()){button.dataset.action='new-contract';button.innerHTML=`${icon('plus')} Solicitar contrato`;}else button.remove();}
  if(page==='team'){const button=$('.heading-actions [data-action="new-ticket"]');if(canManage()){button.dataset.action='new-user';button.innerHTML=`${icon('plus')} Adicionar usuário`;}else button.remove();}
  if(page==='providers'){const button=$('.heading-actions [data-action="new-ticket"]');if(canManage()){button.dataset.action='new-provider';button.innerHTML=`${icon('plus')} Cadastrar prestador`;}else button.remove();}
  if(page==='notifications')$('.heading-actions [data-action="new-ticket"]').remove();
}
pages.team=['Equipe','Usuários, funções e acessos.'];
function content(){const render=({inspections:inspectionsPage,contracts:contractsPage,notifications:notificationsPage,overview:overview,tickets:ticketsPage,properties:propertiesPage,providers:providersPage,agenda:agendaPage,reports:reportsPage,team:teamPage}[page]||inspectionsPage);return `${page!=='contracts'?contractAlertsBanner():''}${render()}`;}
function navigate(next,nextFilters={}){page=next;filters=nextFilters;history.replaceState(null,'','#'+next);shell();}
async function load(){state=await api('/state');knownNotificationIds=new Set((state.notifications?.items||[]).map(n=>n.id));shell();}
function updateNotificationBadge(){const link=$('[data-nav="notifications"]');if(!link)return;const count=state.notifications?.unread_count||0,badge=link.querySelector('b');if(count){if(badge)badge.textContent=String(count);else link.insertAdjacentHTML('beforeend',`<b>${count}</b>`);}else badge?.remove();}
async function refreshNotifications(){const next=await api('/notifications'),fresh=next.items.filter(n=>!knownNotificationIds.has(n.id)&&!n.read_at);state.notifications=next;knownNotificationIds=new Set(next.items.map(n=>n.id));updateNotificationBadge();if(fresh.length){const n=fresh[0];if(n.type==='contract')toast('Contrato enviado à gestora.');else{const protocol=inspectionDisplayProtocol(n.protocol);toast(`Vistoria${protocol?` ${protocol}`:''} concluída e aguardando sua revisão.`);}}if(page==='notifications')$('#page-content').innerHTML=content();}
function filtered(){return state.tickets.filter(t=>(!filters.status||t.status===filters.status)&&(!filters.priority||t.priority===filters.priority)&&(!filters.category||t.category===filters.category)&&(!filters.assignee||t.assignee_id===filters.assignee)&&(!filters.overdue||overdue(t))&&(!filters.pending||t.pending_quotes>0)&&(!filters.open||active(t))&&(!filters.property||t.property_id===filters.property)&&(!filters.q||fold(`${t.protocol} ${t.title} ${t.property_name} ${t.unit} ${t.address_snapshot} ${t.requester}`).includes(fold(filters.q))));}
function metric(label,value,sub,i,action,tone=''){return `<button class="metric ${tone}" data-action="metric" data-filter="${action}"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(i)}</span></div><strong>${value}</strong><div class="metric-bottom">${sub}<span>${icon('arrow')}</span></div></button>`;}
function inspectionBadge(status){return `<span class="badge inspection-${h(status)}">${h(inspectionStatusNames[status]||status)}</span>`;}
function inspectionDisplayProtocol(protocol){return /^HIST-\d{4}$/i.test(protocol||'')?'':String(protocol||'');}
function inspectionDisplayPropertyCode(i){const code=String(i.property_code_snapshot||i.property_code||i.property?.code||'');return /^HIST-\d{4}$/i.test(i.protocol||'')&&/^HIST-(?:[0-9A-F]{16}|[0-9A-F]{14}-\d+)$/i.test(code)?'':code;}
function inspectionScheduleLabel(i){return i.status==='new'&&i.scheduled_at?'Aguardando aceite':i.status==='received'?'Aceita pelo vistoriador':inspectionStatusNames[i.status];}
function inspectionTimeRange(i){return i.scheduled_at?`${i.scheduled_at.slice(11,16)}–${i.scheduled_end?.slice(11,16)||'?'}`:'';}
function suggestedInspectionDuration(propertyId,kind){
  const rows=state.inspections.filter(i=>i.kind===kind&&i.duration_minutes>0&&!['cancelled','no_contract'].includes(i.status));
  const code=state.properties.find(p=>p.id===propertyId)?.code;
  const same=rows.filter(i=>i.property_code===code).sort((a,b)=>b.updated_at.localeCompare(a.updated_at));
  if(same.length)return same[0].duration_minutes;
  const values=rows.map(i=>i.duration_minutes).sort((a,b)=>a-b);
  return values.length?Math.ceil(values[Math.floor(values.length/2)]/15)*15:60;
}
function filteredInspections(){const status=filters.inspection_status;return state.inspections.filter(i=>(status==='all'||(status?i.status===status:!['completed','finalized','cancelled'].includes(i.status)))&&(!filters.inspection_inspector||i.inspector_id===filters.inspection_inspector)&&(!filters.inspection_requester||i.requester_id===filters.inspection_requester));}
function inspectionCard(i){
  const protocol=inspectionDisplayProtocol(i.protocol),propertyCode=inspectionDisplayPropertyCode(i),address=String(i.address_snapshot||'').trim();
  const propertyName=String(i.property_name||'').trim(),showAddress=address&&fold(address)!==fold(propertyName);
  return `<button class="inspection-card" data-inspection="${h(i.id)}"><span class="inspection-card-top"><span class="inspection-card-tags"><span class="inspection-kind-tag inspection-kind-${h(i.kind)}"><small>Tipo de vistoria</small><strong>${h(inspectionKindNames[i.kind]||i.kind)}</strong></span>${protocol?`<span class="inspection-protocol"><small>Protocolo</small><strong>${h(protocol)}</strong></span>`:''}</span><span class="badge inspection-${h(i.status)}">Situação · ${h(inspectionStatusNames[i.status]||i.status)}</span></span><span class="inspection-card-property"><small>Imóvel / unidade</small><strong>${h(propertyName||'Não identificado')}</strong></span>${propertyCode?`<span class="inspection-card-code"><small>Código do imóvel</small><strong>${h(propertyCode)}</strong></span>`:''}${showAddress?`<span class="inspection-card-address"><small>Endereço</small><strong>${h(address)}</strong></span>`:''}<span class="inspection-card-fields"><span><small>Prazo</small><strong>${i.deadline_at?h(date(i.deadline_at)):'Não informado'}</strong></span><span><small>Vistoriador</small><strong>${h(i.inspector_name||'Não atribuído')}</strong></span><span><small>Agendamento</small><strong>${i.scheduled_at?`${h(date(i.scheduled_at))} · ${h(inspectionTimeRange(i))}`:i.status==='new'?'Aguardando agendamento':'Não agendado'}</strong></span></span>${i.status==='new'&&i.scheduled_at?'<span class="schedule-pending">Aceite do horário · aguardando vistoriador</span>':''}<span class="inspection-card-requester"><small>Solicitante</small><strong>${h(i.requester_name||'Não informado')}</strong></span></button>`;
}
function inspectionsPage(){
  if(state.user.role==='finance')return empty('Acesso restrito','Vistorias ficam disponíveis para a equipe de gestão e atendimento.');
  const rows=filteredInspections(),staff=state.users.filter(u=>['admin','staff'].includes(u.role));
  const statuses=Object.entries(inspectionStatusNames).filter(([status])=>filters.inspection_status==='all'||(filters.inspection_status?status===filters.inspection_status:!['completed','finalized','cancelled'].includes(status)));
  const list=inspectionView==='list'?`<div class="inspection-list">${rows.map(inspectionCard).join('')||empty('Nenhum pedido encontrado','Crie um pedido de vistoria para começar.',`<button class="btn primary" data-action="new-inspection">${icon('plus')} Novo pedido</button>`)}</div>`:`<div class="inspection-board">${statuses.map(([status,label])=>{const items=rows.filter(i=>i.status===status);return `<section class="inspection-column ${status==='new'?'is-priority':''}"><h2><span class="inspection-status-title">${h(label)}${status==='new'?'<small>Prioridade</small>':''}</span><span>${items.length}</span></h2>${items.map(inspectionCard).join('')||'<p class="muted small-text">Nenhum pedido</p>'}</section>`;}).join('')}</div>`;
  const statusOptions=`<option value="" ${filters.inspection_status?'':'selected'}>Em aberto</option><option value="all" ${filters.inspection_status==='all'?'selected':''}>Todos os status</option>${options(inspectionStatusNames,filters.inspection_status)}`;
  const statusNote=filters.inspection_status?'':'<p class="inspection-filter-note">Canceladas, concluídas e finalizadas ficam ocultas até você selecionar o status no filtro.</p>';
  return `<section class="panel"><div class="list-toolbar"><div class="tabs" role="group" aria-label="Visualização de vistorias"><button class="tab ${inspectionView==='list'?'active':''}" data-action="inspection-view" data-view="list">Lista <b>${rows.length}</b></button><button class="tab ${inspectionView==='kanban'?'active':''}" data-action="inspection-view" data-view="kanban">Kanban</button></div><span class="result-count">${rows.length} pedido${rows.length===1?'':'s'}</span></div><div class="filterbar"><select data-filter="inspection_status" aria-label="Filtrar por situação">${statusOptions}</select><select data-filter="inspection_inspector" aria-label="Filtrar por vistoriador"><option value="">Todos os vistoriadores</option>${staff.map(u=>`<option value="${h(u.id)}" ${filters.inspection_inspector===u.id?'selected':''}>${h(u.name)}</option>`).join('')}</select><select data-filter="inspection_requester" aria-label="Filtrar por solicitante"><option value="">Todos os solicitantes</option>${staff.map(u=>`<option value="${h(u.id)}" ${filters.inspection_requester===u.id?'selected':''}>${h(u.name)}</option>`).join('')}</select>${Object.keys(filters).some(k=>k.startsWith('inspection_')&&filters[k])?'<button class="text-btn" data-action="clear-inspection-filters">Limpar</button>':''}</div>${statusNote}${list}</section>`;
}
function notificationsPage(){
  if(state.user.role==='finance')return empty('Acesso restrito','Avisos de vistorias ficam disponíveis para a equipe de gestão e atendimento.');
  const {items=[]}=state.notifications||{};
  return `<section class="panel"><div class="panel-heading"><div><h2>Avisos da operação</h2><p>Conclusões de vistorias e contratos enviados para revisão.</p></div><span class="count-pill">${state.notifications?.unread_count||0} não lidos</span></div>${items.length?`<div class="notification-list">${items.map(n=>{
    if(n.type==='contract')return `<article class="record-card notification-card ${n.read_at?'':'unread'}"><div class="record-header"><span class="record-icon">${icon('file')}</span><div><h3>Contrato enviado à gestora</h3><p>${h(stamp(n.created_at))}</p></div>${n.read_at?'':'<span class="count-pill">Novo</span>'}</div><p class="description">A equipe enviou o pedido de ${h(n.kind==='other'?n.manual_reason:contractKindNames[n.kind])} do imóvel ${h(n.property_code||'sem código')} · ${h(n.address_snapshot)} para sua revisão.</p><div class="record-actions"><button class="btn secondary" data-action="open-notification" data-id="${h(n.id)}">Ver contrato ${icon('arrow')}</button></div></article>`;
    const protocol=inspectionDisplayProtocol(n.protocol);return `<article class="record-card notification-card ${n.read_at?'':'unread'}"><div class="record-header"><span class="record-icon">${icon('alert')}</span><div><h3>Vistoria concluída${protocol?` · ${h(protocol)}`:''}</h3><p>${h(stamp(n.created_at))}</p></div>${n.read_at?'':'<span class="count-pill">Novo</span>'}</div><p class="description">${h(n.inspector_name||'O vistoriador')} concluiu ${h(inspectionKindNames[n.kind]||'a vistoria')} de ${h(inspectionDisplayPropertyCode(n)||'imóvel sem código')} · ${h(n.address_snapshot)}.</p>${n.completion_note?`<p class="notification-result"><strong>Resultado informado:</strong> ${h(n.completion_note)}</p>`:''}<p class="muted">Aguarda sua revisão e finalização.</p><div class="record-actions"><button class="btn secondary" data-action="open-notification" data-id="${h(n.id)}">Ver vistoria ${icon('arrow')}</button></div></article>`;
  }).join('')}</div>`:empty('Nenhum aviso por enquanto','Avisos de vistoria e de contratos aparecerão aqui.')}</section>`;
}
function contractBadge(c){const status=c.overdue?'overdue':c.status;return `<span class="badge contract-${h(status)}">${c.overdue?'Atrasado':h(contractStatusNames[c.status]||c.status)}</span>`;}
function contractCard(c){return `<article class="record-card contract-card"><div class="record-header"><span class="record-icon">${icon('file')}</span><div><h3>${h(contractKindNames[c.kind]||c.manual_reason)}${c.kind==='other'?`: ${h(c.manual_reason)}`:''}</h3><p>${h(c.property_code_snapshot)} · ${h(c.property_name)}${c.unit?` · ${h(c.unit)}`:''}</p></div>${contractBadge(c)}</div><div class="contract-card-meta"><span><small>Solicitado em</small>${h(stamp(c.requested_at))}</span><span><small>Prazo para confecção</small><strong class="${c.overdue?'text-amber':''}">${h(date(c.deadline_at))}</strong></span><span><small>Solicitante</small>${h(c.requester_name)}</span></div>${c.overdue?`<p class="contract-delay-note">${c.delay_reason?`Justificativa: ${h(c.delay_reason)}`:'Atraso sem justificativa registrada.'}</p>`:''}<div class="record-actions"><button class="btn secondary" data-contract="${h(c.id)}">Abrir solicitação ${icon('arrow')}</button></div></article>`;}
function contractsPage(){
  if(!canUseContracts())return empty('Acesso restrito','Solicitações de contrato ficam disponíveis para a equipe de gestão e atendimento.');
  const contracts=state.contracts||[],late=contracts.filter(c=>c.overdue),requested=contracts.filter(c=>c.status==='requested'),inProgress=contracts.filter(c=>c.status==='in_progress'),sent=contracts.filter(c=>c.status==='sent_to_manager');
  const dueToday=contracts.filter(c=>c.status!=='sent_to_manager'&&c.deadline_at===today());
  return `<div class="contract-metrics"><article><span>Solicitados</span><strong>${requested.length}</strong></article><article><span>Em confecção</span><strong>${inProgress.length}</strong></article><article class="${late.length?'is-late':''}"><span>Atrasados</span><strong>${late.length}</strong></article><article><span>Enviados à gestora</span><strong>${sent.length}</strong></article></div>${late.length||dueToday.length?`<section class="contract-alert-banner" role="status">${icon('alert')}<div><strong>${late.length?`${late.length} contrato${late.length===1?'':'s'} com prazo vencido`:`${dueToday.length} contrato${dueToday.length===1?'':'s'} com prazo hoje`}</strong><p>${late.some(c=>!c.delay_reason)?'Há atraso sem justificativa registrada.':'Confira as justificativas e o andamento.'}</p></div></section>`:''}<section class="panel"><div class="panel-heading"><div><h2>Solicitações de confecção</h2><p>Imóvel, prazo e cada etapa ficam registrados no histórico.</p></div></div>${contracts.length?`<div class="contract-list">${contracts.map(contractCard).join('')}</div>`:empty('Nenhuma solicitação de contrato','A Gestão pode abrir pedidos de ocupação, aditivo ou outro motivo.')}</section>`;
}
function contractAlertsBanner(){
  if(!canUseContracts())return '';
  const alerts=(state.contracts||[]).filter(c=>c.status!=='sent_to_manager'&&(c.overdue||c.deadline_at===today()));
  if(!alerts.length)return '';
  const overdueCount=alerts.filter(c=>c.overdue).length;
  return `<section class="contract-alert-banner overview-contract-alert" role="status">${icon('alert')}<div><strong>${overdueCount?`${overdueCount} contrato${overdueCount===1?'':'s'} atrasado${overdueCount===1?'':'s'}`:'Prazo de contrato hoje'}</strong><p>${alerts.some(c=>!c.delay_reason&&c.overdue)?'Registre a justificativa de atraso e acompanhe o envio à gestora.':'Confira as solicitações com prazo próximo ou vencido.'}</p></div><button class="text-btn" data-nav="contracts">Ver contratos ${icon('arrow')}</button></section>`;
}
function monthLabel(){return new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(new Date(`${inspectionMonth}-01T12:00:00`));}
function inspectionAgendaRow(i){const protocol=inspectionDisplayProtocol(i.protocol),propertyCode=inspectionDisplayPropertyCode(i);return `<button class="agenda-row" data-inspection="${h(i.id)}"><span class="date-tile"><b>${h(i.scheduled_at.slice(8,10))}</b><small>${h(date(i.scheduled_at).replace(/^\d+\s*(de)?\s*/,''))}</small></span><span class="agenda-time">${h(inspectionTimeRange(i))}</span><span class="agenda-description"><strong>${h(inspectionKindNames[i.kind])}${protocol?` · ${h(protocol)}`:''}</strong><small>${propertyCode?`${h(propertyCode)} · `:''}${h(i.property_name)} · ${h(i.unit)}</small></span><span class="agenda-provider">${h(i.inspector_name||'Sem vistoriador')}<small>${h(inspectionScheduleLabel(i))}</small></span>${icon('arrow')}</button>`;}
function overview(){
  const open=state.tickets.filter(active),late=open.filter(overdue),pending=state.tickets.filter(t=>t.pending_quotes>0);
  const visits=state.orders.filter(o=>o.status==='scheduled'&&o.scheduled_at.slice(0,10)>=today());
  const costs=state.costs.reduce((a,c)=>a+c.amount,0);
  const attention=[...open].sort((a,b)=>(overdue(b)-overdue(a))||(['urgent','high','normal','low'].indexOf(a.priority)-['urgent','high','normal','low'].indexOf(b.priority))||a.due_date.localeCompare(b.due_date)).slice(0,5);
  return `<section class="metrics" aria-label="Indicadores da operação">${metric('Chamados abertos',open.length,`<span class="${late.length?'text-amber':''}">${late.length?`${late.length} precisa${late.length>1?'m':''} de atenção ao prazo`:'Prazos em dia'}</span>`,'ticket','open')}${metric('Aguardando aprovação',pending.length,'Orçamentos para decidir','clock','pending')}${metric('Próximas visitas',visits.length,'Agendamentos confirmados','calendar','agenda')}${metric('Custo registrado',money(costs),'Total gerencial da carteira','wallet','reports','money-metric')}</section><div class="overview-grid"><section class="panel attention-panel"><div class="panel-heading"><div><h2>Chamados que precisam de você <span class="count-pill">${open.length}</span></h2><p>Os próximos passos da sua equipe.</p></div><button class="text-btn" data-nav="tickets">Ver todos ${icon('arrow')}</button></div>${attention.length?table(attention,true):empty('Tudo em dia por aqui','Os novos chamados aparecerão neste espaço.')}<div class="panel-foot">${icon('check')} Cada atualização fica no histórico do imóvel.</div></section><div class="right-stack"><section class="panel visits-panel"><div class="panel-heading"><div><h2>Próximas visitas</h2><p>Quem vai, onde e quando.</p></div><span class="heading-icon">${icon('calendar')}</span></div>${visits.length?visits.slice(0,3).map(o=>`<button class="visit-item" data-ticket="${h(o.ticket_id)}"><span class="date-tile"><b>${h(o.scheduled_at.slice(8,10))}</b><small>${h(date(o.scheduled_at).replace(/^\d+\s*(de)?\s*/,''))}</small></span><span class="visit-info"><strong>${h(o.property_name)}</strong><span>${h(o.unit)} · ${h(o.scheduled_at.slice(11))}</span><small>${h(o.provider_name)}</small></span>${icon('arrow')}</button>`).join(''):empty('Agenda livre','As visitas agendadas aparecerão aqui.')}<button class="text-btn full-link" data-nav="agenda">Abrir agenda ${icon('arrow')}</button></section><section class="care-card"><span class="care-icon">${icon('home')}</span><div><span class="eyebrow">GESTÃO QUE CUIDA</span><h3>Um histórico.<br> Mais tranquilidade.</h3><p>Cada manutenção fica conectada ao imóvel, mesmo quando a locação muda.</p><button class="text-btn" data-nav="properties">Explorar imóveis ${icon('arrow')}</button></div><div class="care-decoration" aria-hidden="true">${icon('leaf')}</div></section></div></div><section class="summary-strip"><div>${icon('building')}<span><strong>${state.properties.length} imóveis</strong><small>na sua carteira</small></span></div><div>${icon('tool')}<span><strong>${state.providers.filter(v=>v.active).length} prestadores</strong><small>para cuidar dos detalhes</small></span></div><div>${icon('check')}<span><strong>${state.tickets.filter(t=>['resolved','closed'].includes(t.status)).length} solucionados</strong><small>em todo o histórico</small></span></div><button class="text-btn" data-nav="reports">Ver a operação em números ${icon('arrow')}</button></section>`;
}
function table(rows,compact=false){
  return `<div class="table-wrap"><table class="tickets-table ${compact?'compact':''}"><thead><tr><th>CHAMADO</th><th>IMÓVEL</th><th>PRIORIDADE</th><th>SITUAÇÃO</th>${compact?'':'<th>RESPONSÁVEL</th>'}<th>PRAZO</th><th><span class="sr-only">Abrir</span></th></tr></thead><tbody>${rows.map(t=>`<tr data-ticket="${h(t.id)}"><td><button class="ticket-title" data-ticket="${h(t.id)}"><small>${h(t.protocol)}</small><strong>${h(t.title)}</strong></button></td><td><span class="cell-main">${h(t.property_name)}</span><small>${h(t.unit)}</small></td><td>${badge(t.priority,'priority')}</td><td>${badge(t.status)}</td>${compact?'':`<td>${t.assignee_name?`<span class="assignee"><span class="avatar tiny">${h(initials(t.assignee_name))}</span>${h(t.assignee_name.split(' ')[0])}</span>`:'<span class="muted">Não atribuído</span>'}</td>`}<td><span class="due ${overdue(t)?'late':''}">${overdue(t)?icon('clock'):''}${h(date(t.due_date))}</span></td><td><button class="row-arrow icon-btn" data-ticket="${h(t.id)}" aria-label="Abrir ${h(t.protocol)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`;
}
function ticketsPage(){
  const rows=filtered();return `<section class="panel"><div class="list-toolbar"><div class="tabs" role="group" aria-label="Situação dos chamados"><button class="tab ${!filters.open&&!filters.pending&&!filters.overdue?'active':''}" data-action="ticket-tab" data-filter="all">Todos <b>${state.tickets.length}</b></button><button class="tab ${filters.open?'active':''}" data-action="ticket-tab" data-filter="open">Em aberto <b>${state.tickets.filter(active).length}</b></button><button class="tab ${filters.overdue?'active':''}" data-action="ticket-tab" data-filter="overdue">Atrasados <b>${state.tickets.filter(overdue).length}</b></button><button class="tab ${filters.pending?'active':''}" data-action="ticket-tab" data-filter="pending">Aprovações <b>${state.tickets.filter(t=>t.pending_quotes>0).length}</b></button></div><span class="result-count">${rows.length} resultado${rows.length===1?'':'s'}</span></div><div class="filterbar"><label class="searchbox">${icon('search')}<input type="search" data-filter="q" placeholder="Buscar chamado, endereço ou titular…" aria-label="Buscar chamados" value="${h(filters.q||'')}"></label><select data-filter="status" aria-label="Filtrar por situação"><option value="">Todas as situações</option>${options(statusNames,filters.status)}</select><select data-filter="priority" aria-label="Filtrar por prioridade"><option value="">Prioridades</option>${options(priorityNames,filters.priority)}</select><select data-filter="assignee" aria-label="Filtrar por responsável"><option value="">Responsáveis</option>${state.users.map(u=>`<option value="${h(u.id)}" ${filters.assignee===u.id?'selected':''}>${h(u.name)}</option>`).join('')}</select>${Object.values(filters).some(Boolean)?'<button class="text-btn" data-action="clear-filters">Limpar</button>':''}</div><div id="ticket-results">${rows.length?table(rows):empty('Nenhum chamado encontrado','Tente ajustar os filtros ou registrar um novo chamado.',`<button class="btn primary" data-action="new-ticket">${icon('plus')} Novo chamado</button>`)}</div></section>`;
}
function propertiesPage(){return `<div class="section-title"><p>${state.properties.length} imóveis cadastrados</p>${canManage()?'<button class="btn secondary" data-action="new-property">'+icon('plus')+' Cadastrar imóvel</button>':''}</div><div class="property-grid">${state.properties.map((p,index)=>{const ts=state.tickets.filter(t=>t.property_id===p.id),opened=ts.filter(active).length,address=p.property_street?[p.property_number,p.property_neighborhood,p.property_city].filter(Boolean).join(' · '):p.address;return `<article class="property-card"><div class="property-visual visual-${index%3}"><span class="property-code">${h(p.code)}</span><div class="property-drawing">${icon('building')}</div><span class="property-unit">${h(p.unit)}</span></div><div class="property-body"><h2>${h(p.property_street||p.name)}</h2><p>${h(address)}</p><dl><div><dt>Titular da locação</dt><dd>${h(p.tenant||'Não informado')}</dd></div><div><dt>Proprietário</dt><dd>${h(p.owner||'Não informado')}</dd></div></dl><button class="property-link" data-action="property-tickets" data-id="${h(p.id)}"><span>${opened?`<i class="small-dot"></i> ${opened} chamado${opened>1?'s':''} em aberto`:'Nenhum chamado aberto'}</span><span>Ver histórico ${icon('arrow')}</span></button></div></article>`;}).join('')}</div>`;}
function providersPage(){
  const canAdmin=canManage();
  return `<div class="section-title"><div><h2>Prestadores de serviços</h2><p>Rede de profissionais e parceiros para vistorias e manutenções.</p></div>${canAdmin?`<button class="btn primary" data-action="new-provider">${icon('plus')} Cadastrar prestador</button>`:''}</div><div class="provider-grid">${state.providers.map((p,i)=>{const osCount=state.orders.filter(o=>o.provider_id===p.id).length;return `<article class="panel provider-card"><div class="provider-top"><span class="provider-avatar tone-${i%3}">${h(initials(p.name))}</span><span class="badge ${p.active?'status-resolved':'status-waiting'}">${p.active?'Ativo':'Inativo'}</span></div><h2>${h(p.name)}</h2><p class="specialty">${icon('tool')} ${h(p.specialty)}</p><div class="provider-contact"><span>${h(p.phone||'Telefone não informado')}</span><span>${h(p.email||'E-mail não informado')}</span></div><div class="provider-bottom"><span>${osCount} OS no histórico</span><div class="provider-card-actions"><button class="text-btn" data-action="provider-agenda" data-id="${h(p.id)}">Agenda ${icon('arrow')}</button>${canAdmin?`<button class="btn secondary" data-action="edit-provider" data-id="${h(p.id)}">Editar</button><button class="btn secondary text-danger" data-action="delete-provider" data-id="${h(p.id)}" title="Excluir prestador">${icon('close')}</button>`:''}</div></div></article>`;}).join('')||empty('Nenhum prestador cadastrado','Cadastre prestadores para atender chamados e ordens de serviço.',canAdmin?`<button class="btn primary" data-action="new-provider">${icon('plus')} Cadastrar prestador</button>`:'')}</div>`;
}
function agendaPage(){
  const inspections=state.inspections.filter(i=>i.scheduled_at&&i.scheduled_at.slice(0,7)===inspectionMonth&&['new','received','in_progress'].includes(i.status)&&(!filters.inspection_inspector||i.inspector_id===filters.inspection_inspector));
  const orders=state.orders.filter(o=>o.scheduled_at.slice(0,7)===inspectionMonth&&o.status!=='cancelled'&&(!filters.provider||o.provider_id===filters.provider));
  const staff=state.users.filter(u=>['admin','staff'].includes(u.role)),inspectors=staff.filter(u=>String(u.job_title||'').toLowerCase()==='vistoriador');
  const open=state.inspections.filter(i=>['new','received'].includes(i.status)).length,inProgress=state.inspections.filter(i=>i.status==='in_progress').length,overdueCount=state.inspections.filter(i=>['new','received','in_progress'].includes(i.status)&&i.deadline_at&&i.deadline_at<today()).length;
  const metrics=`<div class="inspection-agenda-metrics"><article><span>Em aberto</span><strong>${open}</strong></article><article><span>Em andamento</span><strong>${inProgress}</strong></article><article><span>Atrasadas</span><strong>${overdueCount}</strong><small>Calculado pelo prazo informado</small></article></div>`;
  return `${metrics}<section class="panel"><div class="panel-heading agenda-month-heading"><div><h2>Vistorias agendadas</h2><p>Horários propostos aguardam aceite; horários aceitos ficam bloqueados.</p><div class="month-nav"><button class="icon-btn" data-action="calendar-month" data-step="-1" aria-label="Mês anterior">‹</button><strong>${h(monthLabel())}</strong><button class="icon-btn" data-action="calendar-month" data-step="1" aria-label="Próximo mês">›</button></div></div><div class="agenda-filters"><select data-filter="inspection_inspector" aria-label="Filtrar por vistoriador"><option value="">Todos os vistoriadores</option>${inspectors.map(u=>`<option value="${h(u.id)}" ${filters.inspection_inspector===u.id?'selected':''}>${h(u.name)}</option>`).join('')}</select></div></div>${inspections.length?`<div class="agenda-list">${inspections.map(inspectionAgendaRow).join('')}</div>`:empty('Nenhuma vistoria agendada neste mês','Crie um pedido e escolha vistoriador, data e horário.')}</section>${orders.length?`<section class="panel agenda-maintenance"><div class="panel-heading"><div><h2>Manutenções agendadas</h2><p>Ordens de serviço deste mês.</p></div><select data-filter="provider" aria-label="Filtrar agenda por prestador"><option value="">Todos os prestadores</option>${providerOptions(filters.provider)}</select></div><div class="agenda-list">${orders.map(o=>`<button class="agenda-row" data-ticket="${h(o.ticket_id)}"><span class="date-tile"><b>${h(o.scheduled_at.slice(8,10))}</b><small>${h(date(o.scheduled_at).replace(/^\d+\s*(de)?\s*/,''))}</small></span><span class="agenda-time">${h(o.scheduled_at.slice(11,16))}</span><span class="agenda-description"><strong>${h(o.scope)}</strong><small>${h(o.property_name)} · ${h(o.unit)} · ${h(o.protocol)}</small></span><span class="agenda-provider">${h(o.provider_name)}<small>${o.kind==='diagnosis'?'Visita diagnóstica':'Execução / retorno'}</small></span><span class="badge order-${h(o.status)}">${orderNames[o.status]}</span>${icon('arrow')}</button>`).join('')}</div></section>`:''}`;
}
function reportsPage(){
  const total=state.costs.reduce((a,c)=>a+c.amount,0),paid=state.costs.reduce((a,c)=>a+c.paid,0),closed=state.tickets.filter(t=>['closed','resolved'].includes(t.status)).length;
  return `<div class="report-note">${icon('chart')}<span>Visão de todo o histórico. Custos são registros gerenciais; o sistema não realiza transferências.</span></div><section class="metrics">${metric('Chamados registrados',state.tickets.length,'Todo o histórico','ticket','all')}${metric('Solucionados',closed,'Solucionados e encerrados','check','all')}${metric('Custo realizado',money(total),'Despesas registradas','wallet','reports')}${metric('Saldo a pagar',money(total-paid),'Pagamentos externos pendentes','clock','reports')}</section><div class="reports-grid"><section class="panel"><div class="panel-heading"><div><h2>Demandas por categoria</h2><p>Distribuição dos chamados da carteira.</p></div></div><div class="category-bars">${state.categories.map(c=>[c,state.tickets.filter(t=>t.category===c).length]).filter(([,n])=>n).map(([c,n])=>`<div class="category-row"><div><span>${h(c)}</span><strong>${n}</strong></div><meter min="0" max="${Math.max(1,state.tickets.length)}" value="${n}" aria-label="${h(c)}: ${n} chamados"></meter></div>`).join('')||'<p class="muted">Sem dados ainda.</p>'}</div></section><section class="panel"><div class="panel-heading"><div><h2>Despesas de manutenção</h2><p>Valor realizado e saldo por chamado.</p></div></div>${state.costs.length?`<div class="table-wrap"><table><thead><tr><th>DESPESA</th><th>PAGADOR</th><th>VALOR</th><th>SALDO</th></tr></thead><tbody>${state.costs.map(c=>`<tr><td><button class="ticket-title" data-ticket="${h(c.ticket_id)}"><small>${h(c.protocol)}</small><strong>${h(c.description)}</strong></button></td><td>${h(c.payer)}</td><td>${money(c.amount)}</td><td>${money(c.amount-c.paid)}</td></tr>`).join('')}</tbody></table></div>`:empty('Sem despesas registradas','Os custos adicionados aos chamados aparecerão aqui.')}</section></div>`;
}

function teamPage(){
  if(!canManage())return empty('Acesso restrito','Somente a Gestão pode configurar os usuários da equipe.');
  const rows=state.adminUsers;
  if(!Array.isArray(rows))return empty('Lista da equipe indisponível','Recarregue a página para carregar os usuários da base.');
  return `<section class="panel team-panel"><div class="panel-heading"><div><h2>Usuários cadastrados</h2><p>Cargo identifica a atuação; acesso controla as permissões.</p></div><span class="count-pill">${rows.length}</span></div><div class="table-wrap"><table class="team-table"><thead><tr><th>Pessoa</th><th>Usuário e e-mail</th><th>Cargo</th><th>Acesso</th><th>Situação</th><th></th></tr></thead><tbody>${rows.map(u=>`<tr><td><strong class="team-name">${h(u.name)}</strong></td><td><strong>@${h(u.username)}</strong><small>${h(u.email)}</small></td><td>${h(userTitleNames[u.job_title]||u.job_title||'A definir')}</td><td>${h(userRoleNames[u.role]||u.role)}</td><td><span class="user-status ${u.active?'is-active':'is-inactive'}">${u.active?'Ativo':'Inativo'}</span></td><td><button class="text-btn" data-action="edit-user" data-id="${h(u.id)}" aria-label="Editar acesso de ${h(u.name)}">Editar</button></td></tr>`).join('')||'<tr><td colspan="6">Nenhum usuário cadastrado.</td></tr>'}</tbody></table></div></section>`;
}
function newContract(values={}){
  if(!canManage()){toast('Somente a Gestão pode abrir solicitações de contrato.',true);return;}
  const staff=state.users.filter(u=>['admin','staff'].includes(u.role));
  const kind=values.kind||'occupation',propertyId=values.property_id||state.properties[0]?.id||'',other=kind==='other';
  const requesterId=values.requested_by||state.user.id;
  editor('Solicitar confecção de contrato',`<p class="form-intro">Os dados do imóvel vêm do cadastro compartilhado com as vistorias. A data prevista de entrega e assinatura será puxada automaticamente na vistoria de ocupação.</p><label>Imóvel / unidade<select name="property_id" required>${state.properties.length?propOptions(propertyId):'<option value="">Cadastre um imóvel para continuar</option>'}</select></label><button type="button" class="text-btn contract-add-property" data-action="contract-add-property">${icon('plus')} Cadastrar novo imóvel</button><div class="form-grid"><label>Operação<select name="kind"><option value="occupation" ${kind==='occupation'?'selected':''}>Ocupação</option><option value="addendum" ${kind==='addendum'?'selected':''}>Aditivo</option><option value="other" ${other?'selected':''}>Outro motivo</option></select></label><label class="contract-reason-field" id="contract-reason-label" ${other?'':'hidden'}>Motivo manual<input id="contract-manual-reason" name="manual_reason" maxlength="400" value="${h(values.manual_reason||'')}" ${other?'required':'disabled'}></label></div><div class="form-grid"><label>Solicitante<select name="requested_by">${staff.map(u=>`<option value="${h(u.id)}" ${requesterId===u.id?'selected':''}>${h(u.name)}</option>`).join('')}</select></label><label>Data prevista para entrega e assinatura<input name="deadline_at" type="date" required value="${h(values.deadline_at||'')}"><small class="field-hint">Prazo de confecção / entrega do imóvel.</small></label></div><label>Informações para a confecção<textarea name="details" rows="4" maxlength="4000" placeholder="Partes, condições e outros dados necessários para preparar o contrato.">${h(values.details||'')}</textarea></label>`,'contract','Criar solicitação');
}
function contractDelayEditor(){
  const c=contractDetail;if(!c)return;
  editor('Justificar atraso',`<p class="form-intro">A justificativa ficará no histórico e visível junto ao prazo do contrato.</p><label>Motivo do atraso<textarea name="reason" rows="4" required maxlength="1000" placeholder="Explique por que o prazo não será cumprido.">${h(c.delay_reason)}</textarea></label>`,'contract-delay','Registrar justificativa');
}
async function openContract(id){try{contractDetail=await api('/contracts/'+id);renderContractDetail();if(!$('#details').open)$('#details').showModal();}catch(e){toast(e.message,true);}}
function renderContractDetail(){
  const c=contractDetail;if(!c)return;
  const reason=c.kind==='other'?c.manual_reason:'';
  const actions=c.status==='requested'?`<button class="btn primary" data-action="start-contract">Iniciar confecção</button>`:c.status==='in_progress'?`<button class="btn primary" data-action="send-contract-manager">Enviar para a gestora</button>`:'';
  const delayAction=c.status!=='sent_to_manager'?`<button class="btn secondary" data-action="justify-contract-delay">${c.delay_reason?'Atualizar justificativa':c.overdue?'Justificar atraso':'Registrar previsão de atraso'}</button>`:'';
  const linkedInspections=c.inspections&&c.inspections.length?`<div class="contract-inspection-card"><div class="section-title slim"><h3>${icon('ticket')} Vistoria de ocupação vinculada</h3></div>${c.inspections.map(insp=>`<div class="linked-inspection-item"><div><strong>${h(insp.protocol)} · <span class="badge inspection-${h(insp.status)}">${h(inspectionStatusNames[insp.status]||insp.status)}</span></strong><p>${insp.inspector_name?`Vistoriador: ${h(insp.inspector_name)}`:'Sem vistoriador'} · ${insp.scheduled_at?`Agendada: ${h(stamp(insp.scheduled_at))}`:'Ainda não agendada'}</p></div><button type="button" class="btn secondary" data-action="open-linked-inspection" data-id="${h(insp.id)}">Abrir vistoria ${icon('arrow')}</button></div>`).join('')}</div>`:'';
  $('#details').innerHTML=`<div class="detail-header"><div class="detail-kicker"><span>Solicitação de contrato</span>${contractBadge(c)}</div><button class="icon-btn close-modal" data-action="close-details" aria-label="Fechar solicitação">${icon('close')}</button><h2 id="detail-title">${h(contractKindNames[c.kind])}${reason?`: ${h(reason)}`:''}</h2><p>${icon('building')} Código do imóvel · ${h(c.property_code_snapshot)} · ${h(c.property.name)}${c.property.unit?` · ${h(c.property.unit)}`:''}</p></div><div class="detail-content contract-detail"><section><h3>Dados e prazos</h3><div class="metadata"><div><span>Código do imóvel (SAMI)</span><strong>${h(c.property_code_snapshot)}</strong></div><div><span>Solicitado em</span><strong>${h(stamp(c.requested_at))}</strong></div><div><span>Solicitante</span><strong>${h(c.requester.name)}</strong></div><div><span>Previsão de entrega/assinatura</span><strong>${h(date(c.deadline_at))}</strong></div><div><span>Enviado à gestora</span><strong>${c.sent_to_manager_at?h(stamp(c.sent_to_manager_at)):'Ainda não enviado'}</strong></div>${c.delayed_at?`<div><span>Justificativa registrada em</span><strong>${h(stamp(c.delayed_at))}</strong></div>`:''}</div><div class="address-box">${icon('home')}<span>${h(c.address_snapshot)}</span></div>${c.overdue?`<div class="contract-alert-banner" role="alert">${icon('alert')}<div><strong>Prazo vencido</strong><p>${c.delay_reason?`Justificativa: ${h(c.delay_reason)}`:'Registre o motivo justificado do atraso.'}</p></div></div>`:c.delay_reason?`<div class="notice">${icon('clock')}<span>Justificativa registrada: ${h(c.delay_reason)}</span></div>`:''}${c.details?`<h3>Informações para a confecção</h3><p class="description">${h(c.details)}</p>`:''}${linkedInspections}<h3 class="history-title">Histórico da solicitação</h3><div class="timeline">${[...c.events].reverse().map(e=>`<article class="timeline-item"><span class="timeline-dot"></span><div><strong>${h(e.action)}</strong><p>${h(e.detail)}</p><small>${h(e.actor)} · ${h(stamp(e.created_at))}</small></div></article>`).join('')}</div></section><div class="record-actions contract-actions">${actions}${delayAction}</div></div><div class="detail-foot">${icon('clock')} Atualizado ${h(stamp(c.updated_at))}<span>Histórico interno</span></div>`;
}
async function openInspection(id){try{inspectionDetail=await api('/inspections/'+id);renderInspectionDetail();if(!$('#details').open)$('#details').showModal();}catch(e){toast(e.message,true);}}
function renderInspectionDetail(){
  const i=inspectionDetail;if(!i)return;const staff=state.users.filter(u=>['admin','staff'].includes(u.role)),inspectors=staff.filter(u=>String(u.job_title||'').toLowerCase()==='vistoriador'||u.id===i.inspector_id);
  const pending=i.status==='new'&&i.scheduled_at&&i.inspector_id===state.user.id;
  const protocol=inspectionDisplayProtocol(i.protocol),propertyCode=inspectionDisplayPropertyCode(i);
  const message=`Olá, ${i.requester.name}. A vistoria${protocol?` ${protocol}`:''} (${inspectionKindNames[i.kind]}) foi concluída. Resultado: ${i.completion_note}`;
  const whatsapp=i.status==='completed'?`<a class="btn secondary full whatsapp-draft" href="https://wa.me/?text=${encodeURIComponent(message)}" target="_blank" rel="noopener noreferrer">${icon('mail')} Preparar WhatsApp para revisão</a>`:'';
  const linkedContractCard=i.contract?`<div class="inspection-contract-card"><div class="section-title slim"><h3>${icon('file')} Contrato vinculado</h3><span class="badge contract-${h(i.contract.status)}">${h(contractStatusNames[i.contract.status]||i.contract.status)}</span></div><div class="metadata"><div><span>Solicitante</span><strong>${h(i.contract.requester_name||i.requester.name)}</strong></div><div><span>Previsão de entrega/assinatura</span><strong>${h(date(i.contract.deadline_at))}</strong></div><div><span>Situação</span><strong>${h(contractStatusNames[i.contract.status]||i.contract.status)}</strong></div>${i.contract.details?`<div class="field-wide"><span>Instruções</span><strong>${h(i.contract.details)}</strong></div>`:''}</div><button type="button" class="btn secondary full" data-action="open-linked-contract" data-id="${h(i.contract.id)}">Ver solicitação de contrato ${icon('arrow')}</button></div>`:'';
  const hasFollowup=i.status!=='new'||Boolean(i.scheduled_at)||Boolean(i.inspector_id)||Boolean(i.reason)||Boolean(i.completion_note);
  const dangerZone=`<div class="inspection-danger-zone">${hasFollowup?`<button type="button" class="btn secondary full text-amber" data-action="reset-inspection" data-id="${h(i.id)}" title="Reverter para Nova e liberar preenchimento">${icon('undo')} Limpar acompanhamento</button>`:''}<button type="button" class="btn secondary full text-danger" data-action="delete-inspection" data-id="${h(i.id)}" data-protocol="${h(protocol||'esta vistoria')}">${icon('close')} Excluir vistoria</button></div>`;
  $('#details').innerHTML=`<div class="detail-header"><div class="detail-kicker">${protocol?`<span>Protocolo · ${h(protocol)}</span>`:''}${inspectionBadge(i.status)}</div><button class="icon-btn close-modal" data-action="close-details" aria-label="Fechar vistoria">${icon('close')}</button><h2 id="detail-title">${h(inspectionKindNames[i.kind])}</h2><p>${icon('building')} ${propertyCode?`Código SAMI · ${h(propertyCode)} · `:''}${h(i.property.name)} · ${h(i.property.unit)}</p></div><div class="detail-content inspection-detail"><div class="inspection-detail-grid"><section><h3>Dados do pedido</h3><div class="metadata"><div><span>Solicitante</span><strong>${h(i.requester.name)}</strong></div><div><span>Registrado no sistema</span><strong>${h(stamp(i.created_at))}</strong></div><div><span>Prazo / Entrega</span><strong>${i.deadline_at?h(date(i.deadline_at)):'Não informado'}</strong></div><div><span>Vistoriador</span><strong>${h(i.inspector?.name||'Não atribuído')}</strong></div><div><span>Agendamento</span><strong>${i.scheduled_at?`${h(stamp(i.scheduled_at))}–${h(i.scheduled_end?.slice(11,16)||'?')}`:'Ainda não agendada'}</strong></div><div><span>Duração prevista</span><strong>${i.duration_minutes?`${i.duration_minutes} minutos`:i.scheduled_at?'A confirmar pelo vistoriador':'Não definida'}</strong></div><div><span>Confirmação</span><strong>${h(inspectionScheduleLabel(i))}</strong></div></div><div class="address-box">${icon('home')}<span>${h(i.address_snapshot)}</span></div>${linkedContractCard}${pending?`<div class="notice schedule-acceptance">${icon('clock')}<span>Este horário foi proposto para você. Aceite ou libere o horário para a equipe sugerir outro.</span><div class="record-actions"><button class="btn primary" data-action="accept-inspection">Aceitar horário</button><button class="btn secondary" data-action="decline-inspection">Não posso neste horário</button></div></div>`:''}${whatsapp}<h3 class="history-title">Histórico do pedido</h3><div class="timeline">${i.events.map(e=>`<div class="timeline-item"><span class="timeline-dot"></span><div><strong>${h(e.action)}</strong><p>${h(e.detail)}</p><small>${h(e.actor)} · ${h(stamp(e.created_at))}</small></div></div>`).join('')}</div></section><aside class="triage-box"><h3>Responsável e acompanhamento</h3><form data-form="inspection-update"><label>Situação<select name="status">${options(inspectionStatusNames,i.status)}</select></label><label>Prazo / Entrega<input type="date" name="deadline_at" value="${h(i.deadline_at||'')}"><small class="field-hint">Prazo de entrega das chaves / assinatura.</small></label><label>Vistoriador<select name="inspector_id"><option value="">Não atribuído</option>${inspectors.map(u=>`<option value="${h(u.id)}" ${i.inspector_id===u.id?'selected':''}>${h(u.name)}</option>`).join('')}</select></label><label>Data e horário<input type="datetime-local" name="scheduled_at" value="${h(i.scheduled_at)}"></label><label>Duração prevista (minutos)<input type="number" name="duration_minutes" min="15" max="480" step="15" value="${h(i.duration_minutes||'')}"></label><small class="field-hint">Expediente: 08:00–11:00 e 13:00–18:00. Duração definida pelo vistoriador. Horário novo aguarda aceite.</small><label>Motivo de cancelamento ou sem contrato<textarea name="reason" rows="3" maxlength="1500">${h(i.reason)}</textarea></label><label>Resultado da vistoria<textarea name="completion_note" rows="4" maxlength="4000">${h(i.completion_note)}</textarea></label><p class="form-error" role="alert"></p><button type="submit" class="btn primary full">Salvar acompanhamento</button></form>${dangerZone}</aside></div></div><div class="detail-foot">${icon('clock')} Registrado em ${h(stamp(i.created_at))} · Atualizado ${h(stamp(i.updated_at))}<span>Gestor Imob</span></div>`;
}
async function openTicket(id){try{detail=await api('/tickets/'+id);detailTab='summary';renderDetail();if(!$('#details').open)$('#details').showModal();}catch(e){toast(e.message,true);}}
function renderDetail(){
  if(!detail)return;const t=detail;
  const tabs=[['summary','Resumo'],['quotes','Orçamentos'],['orders','Ordens de serviço'],['costs','Custos'],['history','Histórico']];
  $('#details').innerHTML=`<div class="detail-header"><div class="detail-kicker"><span>${h(t.protocol)}</span>${badge(t.status)}${badge(t.priority,'priority')}</div><button class="icon-btn close-modal" data-action="close-details" aria-label="Fechar chamado">${icon('close')}</button><h2 id="detail-title">${h(t.title)}</h2><p>${icon('building')} ${h(t.property.name)} · ${h(t.property.unit)}</p></div><div class="detail-tabs" role="group" aria-label="Seções do chamado">${tabs.map(([key,label])=>`<button class="tab ${detailTab===key?'active':''}" data-action="detail-tab" data-tab="${key}">${label}${key==='quotes'&&t.quotes.length?` <b>${t.quotes.length}</b>`:''}</button>`).join('')}</div><div class="detail-content">${({summary:detailSummary,quotes:detailQuotes,orders:detailOrders,costs:detailCosts,history:detailHistory}[detailTab])()}</div><div class="detail-foot">${icon('clock')} Atualizado ${h(stamp(t.updated_at))}<span>Espaço interno da imobiliária</span></div>`;
}
function detailSummary(){const t=detail;return `<div class="detail-summary-grid"><section><h3>O que aconteceu</h3><p class="description">${h(t.description)}</p><div class="metadata"><div><span>Imóvel / unidade</span><strong>${h(t.property.code)} · ${h(t.property.unit)}</strong></div><div><span>Categoria</span><strong>${h(t.category)}</strong></div><div><span>Solicitante</span><strong>${h(t.requester)}</strong></div><div><span>Contato</span><strong>${h(t.contact)}</strong></div><div><span>Titular na abertura</span><strong>${h(t.tenant_snapshot||'Sem titular / área comum')}</strong></div><div><span>Recebido por</span><strong>${h(t.source)}</strong></div></div><div class="address-box">${icon('home')}<span>${h(t.address_snapshot)}</span></div><div class="section-title slim"><h3>Anexos <span class="count-pill">${t.attachments.length}</span></h3><button class="text-btn" data-action="attachment">${icon('plus')} Anexar</button></div>${t.attachments.length?`<div class="attachment-list">${t.attachments.map(a=>`<a href="/api/attachments/${h(a.id)}" class="attachment" download>${icon('file')}<span>${h(a.name)}<small>${Math.ceil(a.size/1024)} KB · Somente equipe</small></span>${icon('arrow')}</a>`).join('')}</div>`:'<p class="muted small-text">Fotos e documentos ficam privados neste espaço.</p>'}<div class="section-title slim"><h3>Notas e comunicação</h3></div>${t.notes.map(n=>`<article class="note"><div><strong>${h(n.author)}</strong><span class="note-audience">${audienceNames[n.audience]}</span><small>${h(stamp(n.created_at))}</small></div><p>${h(n.body)}</p></article>`).join('')}<form data-form="note" class="note-form"><label class="sr-only" for="note-body">Nova anotação</label><textarea id="note-body" name="body" rows="3" required maxlength="6000" placeholder="Registre uma atualização ou próximo passo…"></textarea><div><select name="audience" aria-label="Público da anotação">${options(audienceNames,'internal')}</select><button class="btn secondary" type="submit">Salvar anotação</button></div><p class="small-text muted">Registros para públicos externos não são enviados nesta versão.</p><p class="form-error" role="alert"></p></form></section><aside class="triage-box"><h3>Triagem e acompanhamento</h3><form data-form="triage"><label>Situação<select name="status">${options(statusNames,t.status)}</select></label><label>Prioridade<select name="priority">${options(priorityNames,t.priority)}</select></label><label>Responsável<select name="assignee_id"><option value="">Não atribuído</option>${state.users.map(u=>`<option value="${h(u.id)}" ${t.assignee_id===u.id?'selected':''}>${h(u.name)}</option>`).join('')}</select></label><label>Prazo<input type="date" name="due_date" value="${h(t.due_date)}" required></label><label>Motivo / confirmação<textarea name="reason" rows="3" placeholder="Espera, cancelamento, reabertura ou quem confirmou a solução">${h(t.waiting_reason)}</textarea></label><label>Solução aplicada<textarea name="solution" rows="3" placeholder="O que foi feito para resolver">${h(t.solution)}</textarea></label><p class="form-error" role="alert"></p><button type="submit" class="btn primary full">Salvar acompanhamento</button></form>${(canManage()||state.user.role==='staff')?`<div class="inspection-danger-zone"><button type="button" class="btn secondary full text-danger" data-action="delete-ticket" data-id="${h(t.id)}" data-protocol="${h(t.protocol||'esta solicitação')}">${icon('close')} Excluir solicitação de manutenção</button></div>`:''}</aside></div>`;}
function detailQuotes(){return `<div class="section-title"><div><h3>Propostas e decisões</h3><p class="muted">Cada revisão preserva a versão anterior.</p></div><button class="btn primary" data-action="new-quote">${icon('plus')} Registrar orçamento</button></div>${detail.quotes.length?[...detail.quotes].reverse().map(q=>`<article class="record-card"><div class="record-header"><span class="record-icon">${icon('file')}</span><div><h3>Orçamento · versão ${q.version}</h3><p>${h(state.providers.find(p=>p.id===q.provider_id)?.name)}</p></div>${badge(q.status,'quote')}</div><p class="description">${h(q.scope)}</p><div class="quote-items">${q.items.map(i=>`<div><span>${h(i.label)}</span><strong>${money(i.cents)}</strong></div>`).join('')}<div class="quote-total"><strong>Total</strong><strong>${money(q.total)}</strong></div></div>${q.approver?`<div class="notice">${icon('check')}<span>Resposta de <strong>${h(q.approver)}</strong> registrada por ${h(q.decision_actor)}.<br>${h(q.decision_note)}</span></div>`:''}${q.status==='pending'&&canManage()?`<div class="record-actions"><button class="btn secondary" data-action="decide-quote" data-id="${h(q.id)}">Registrar resposta externa ${icon('arrow')}</button></div>`:''}</article>`).join(''):empty('Vamos organizar o orçamento?','Registre prestador, escopo e valores antes de autorizar o reparo.')}`;}
function detailOrders(){return `<div class="section-title"><div><h3>Visitas e execução</h3><p class="muted">Diagnóstico e reparo têm autorizações próprias.</p></div>${canManage()?`<button class="btn primary" data-action="new-order">${icon('plus')} Agendar OS</button>`:''}</div>${detail.orders.length?detail.orders.map(o=>`<article class="record-card"><div class="record-header"><span class="record-icon">${icon('tool')}</span><div><h3>${o.kind==='diagnosis'?'Visita diagnóstica':o.kind==='return'?'Retorno':'Execução do reparo'}</h3><p>${h(state.providers.find(p=>p.id===o.provider_id)?.name)}</p></div><span class="badge order-${h(o.status)}">${orderNames[o.status]}</span></div><p class="description">${h(o.scope)}</p><div class="inline-metadata"><span>${icon('calendar')} ${h(date(o.scheduled_at))} às ${h(o.scheduled_at.slice(11))}</span><strong>${money(o.authorized_cents)} autorizado</strong></div><div class="notice">${icon('check')}<span>Autorização de ${h(o.authorization_by)} registrada pela equipe.<br>${h(o.authorization_note)}</span></div>${o.completion?`<h4>Registro de execução</h4><p class="description">${h(o.completion)}</p><p class="muted">${h(o.evidence_note)}</p>`:''}${!['completed','cancelled'].includes(o.status)?`<div class="record-actions"><button class="btn secondary" data-action="update-order" data-id="${h(o.id)}">Atualizar execução ${icon('arrow')}</button></div>`:''}</article>`).join(''):empty('Nenhuma OS agendada','Você pode autorizar primeiro uma visita de diagnóstico, mesmo sem orçamento de reparo.')}`;}
function detailCosts(){return `<div class="section-title"><div><h3>Custos e pagamentos externos</h3><p class="muted">Controle gerencial, sem movimentação de dinheiro.</p></div>${canFinance()?`<button class="btn primary" data-action="new-cost">${icon('plus')} Registrar despesa</button>`:''}</div>${detail.costs.length?detail.costs.map(c=>`<article class="record-card"><div class="record-header"><span class="record-icon">${icon('wallet')}</span><div><h3>${h(c.description)}</h3><p>${h(c.payer)} · Vencimento ${h(date(c.due_date))}</p></div><span class="badge ${c.paid===c.amount?'status-resolved':'status-waiting'}">${c.paid===c.amount?'Pago':c.paid?'Parcialmente pago':'A pagar'}</span></div><div class="cost-numbers"><div><small>Realizado</small><strong>${money(c.amount)}</strong></div><div><small>Pago por fora</small><strong>${money(c.paid)}</strong></div><div><small>Saldo</small><strong>${money(c.amount-c.paid)}</strong></div></div>${c.payment_note?`<p class="muted">${h(c.payment_note)}</p>`:''}${canFinance()&&c.paid<c.amount?`<div class="record-actions"><button class="btn secondary" data-action="pay-cost" data-id="${h(c.id)}">Registrar pagamento externo</button></div>`:''}</article>`).join(''):empty('Nenhuma despesa registrada','O orçamento aprovado e o custo efetivo são registros diferentes.')}`;}
function detailHistory(){return `<h3 class="history-title">Cada passo fica registrado.</h3><div class="timeline">${[...detail.events].reverse().map(e=>`<article class="timeline-item"><span class="timeline-dot"></span><div><strong>${h(e.action)}</strong><p>${h(e.detail)}</p><small>${h(e.actor)} · ${h(stamp(e.created_at))}</small></div></article>`).join('')}</div>`;}

function confirmModal({ title = 'Confirmação', message, detailText = '', confirmText = 'Confirmar', cancelText = 'Cancelar', danger = false }) {
  return new Promise((resolve) => {
    const d = $('#confirm-modal');
    if (!d) { resolve(window.confirm(message + (detailText ? '\n\n' + detailText : ''))); return; }
    d.innerHTML = `<div class="editor-heading" style="padding:18px 24px 16px;"><div><span class="eyebrow">GESTOR IMOB</span><h2 id="confirm-modal-title" style="font-size:17px;margin:0;">${h(title)}</h2></div><button class="icon-btn" data-action="confirm-modal-close" aria-label="Fechar">${icon('close')}</button></div><div class="confirm-body"><p class="confirm-title">${h(message)}</p>${detailText ? `<p class="confirm-text">${h(detailText)}</p>` : ''}</div><div class="confirm-footer"><button type="button" class="btn secondary" data-action="confirm-modal-cancel">${h(cancelText)}</button><button type="button" class="btn primary" style="${danger ? 'background:#b05a4e;border-color:#b05a4e;color:#fff;' : ''}" data-action="confirm-modal-ok">${h(confirmText)}</button></div>`;
    let resolved = false;
    const finish = (val) => {
      if (resolved) return;
      resolved = true;
      d.close();
      resolve(val);
    };
    d.querySelector('[data-action="confirm-modal-ok"]').onclick = () => finish(true);
    d.querySelector('[data-action="confirm-modal-cancel"]').onclick = () => finish(false);
    d.querySelector('[data-action="confirm-modal-close"]').onclick = () => finish(false);
    d.oncancel = () => finish(false);
    d.showModal();
  });
}
function editor(title,body,form,submit='Salvar'){const d=$('#editor');d.innerHTML=`<div class="editor-heading"><div><span class="eyebrow">GESTOR IMOB</span><h2 id="editor-title">${h(title)}</h2></div><button class="icon-btn" data-action="close-editor" aria-label="Fechar formulário">${icon('close')}</button></div><form data-form="${form}"><div class="editor-body">${body}<p class="form-error" role="alert"></p></div><div class="editor-footer"><button type="button" class="btn secondary" data-action="close-editor">Cancelar</button><button type="submit" class="btn primary">${h(submit)} ${icon('arrow')}</button></div></form>`;if(!d.open)d.showModal();}
function newTicket(){
  if(!state.properties.length){toast('Cadastre um imóvel antes de abrir o chamado.',true);if(canManage())newProperty();return;}
  const p=state.properties[0];editor('Novo chamado',`<p class="form-intro">Registre a demanda. Os próximos passos ficam todos aqui.</p><label>Imóvel / unidade<select name="property_id">${propOptions()}</select></label><div class="form-grid"><label>Nome do solicitante<input name="requester" value="${h(p.tenant||'') }" required maxlength="150"></label><label>Contato<input name="contact" value="${h(p.contact)}" required maxlength="180" placeholder="Telefone ou e-mail"></label></div><label>Qual é o problema?<input name="title" required maxlength="150" placeholder="Ex.: vazamento na pia da cozinha"></label><div class="form-grid"><label>Tipo do problema<select name="category">${state.categories.map(c=>`<option>${h(c)}</option>`).join('')}</select></label><label>Prioridade<select name="priority">${options(priorityNames,'normal')}</select></label></div><label>Descrição<textarea name="description" rows="4" required maxlength="6000" placeholder="O que aconteceu, em qual local e desde quando?"></textarea></label><div class="form-grid"><label>Recebido por<select name="source"><option>WhatsApp</option><option>Telefone</option><option>E-mail</option><option>Presencial</option></select></label><label>Prazo inicial<input name="due_date" type="date" required value="${today()}"></label></div><div class="notice">${icon('file')}<span>Depois de salvar, você pode anexar fotos e documentos no chamado.</span></div>`,'ticket','Criar chamado');
}
function findMatchingContract(propertyId,kind,requesterId){
  if(kind!=='occupation'||!propertyId)return null;
  const list=state.contracts||[];
  const exact=list.find(c=>c.property_id===propertyId&&c.kind==='occupation'&&c.requested_by===requesterId);
  if(exact)return exact;
  return list.find(c=>c.property_id===propertyId&&c.kind==='occupation')||null;
}
function inspectionContractBannerHtml(propertyId,kind,requesterId){
  if(kind!=='occupation')return '<div id="inspection-contract-banner"></div>';
  const c=findMatchingContract(propertyId,kind,requesterId);
  if(c){
    return `<div class="contract-linked-banner" id="inspection-contract-banner"><div class="contract-linked-header"><span class="contract-linked-tag">${icon('file')} Contrato de ocupação vinculado</span><span class="badge contract-${h(c.status)}">${h(contractStatusNames[c.status]||c.status)}</span></div><div class="contract-linked-body"><p>Solicitante: <strong>${h(c.requester_name)}</strong> · Previsão de entrega e assinatura: <strong>${h(date(c.deadline_at))}</strong></p>${c.details?`<small class="contract-linked-details">Instruções: "${h(c.details)}"</small>`:''}</div><input type="hidden" name="contract_id" value="${h(c.id)}"></div>`;
  }
  return `<div class="contract-empty-hint" id="inspection-contract-banner">${icon('alert')}<span>Nenhum contrato de ocupação encontrado para este imóvel/solicitante.</span>${canManage()?`<button type="button" class="text-btn" data-action="quick-contract-for-inspection" data-property="${h(propertyId)}">+ Solicitar confecção de contrato</button>`:''}</div>`;
}
function syncInspectionContract(form){
  if(!form||form.dataset.form!=='inspection')return;
  const propertyId=form.elements.property_id?.value;
  const kind=form.elements.kind?.value;
  const requesterId=form.elements.requester_id?.value;
  const banner=$('#inspection-contract-banner');
  if(banner){banner.outerHTML=inspectionContractBannerHtml(propertyId,kind,requesterId);}
  if(kind==='occupation'){
    const c=findMatchingContract(propertyId,kind,requesterId);
    if(c?.deadline_at&&form.elements.deadline_at){
      if(!form.elements.deadline_at.value||form.elements.deadline_at.dataset.auto==='1'){
        form.elements.deadline_at.value=c.deadline_at;
        form.elements.deadline_at.dataset.auto='1';
      }
    }
  }
}
function newInspection(values={}){
  if(!['admin','staff'].includes(state.user.role)){toast('Esta área exige acesso da equipe de vistorias.',true);return;}
  const staff=state.users.filter(u=>['admin','staff'].includes(u.role)),inspectors=staff.filter(u=>String(u.job_title||'').toLowerCase()==='vistoriador');
  const propertyId=values.property_id||state.properties[0]?.id,kind=values.kind||'occupation';
  const requesterId=values.requester_id||state.user.id;
  const matchingContract=findMatchingContract(propertyId,kind,requesterId);
  const deadline=values.deadline_at||(kind==='occupation'&&matchingContract?.deadline_at?matchingContract.deadline_at:'');
  editor('Novo pedido de vistoria',`<p class="form-intro">Escolha o imóvel, o tipo e a data prevista de entrega. A data e horário propostos são opcionais para adiantar a agenda; a duração será definida pelo vistoriador.</p><label>Imóvel / unidade<select name="property_id" required>${propOptions(propertyId)}</select></label>${['admin','staff'].includes(state.user.role)?`<button type="button" class="text-btn inspection-add-property" data-action="inspection-add-property">${icon('plus')} Cadastrar novo imóvel</button>`:''}<label>Tipo de vistoria<select name="kind"><option value="occupation" ${kind==='occupation'?'selected':''}>Ocupação</option><option value="move_out" ${kind==='move_out'?'selected':''}>Desocupação</option><option value="reinspection" ${kind==='reinspection'?'selected':''}>Revistoria</option><option value="visit" ${kind==='visit'?'selected':''}>Visita</option><option value="plate_photos" ${kind==='plate_photos'?'selected':''}>Fotos de placa</option></select></label>${inspectionContractBannerHtml(propertyId,kind,requesterId)}<div class="form-grid"><label>Solicitante<select name="requester_id">${staff.map(u=>`<option value="${h(u.id)}" ${requesterId===u.id?'selected':''}>${h(u.name)}</option>`).join('')}</select></label><label>Prazo / Entrega<input name="deadline_at" type="date" value="${h(deadline)}" ${deadline&&matchingContract?'data-auto="1"':''}><small class="field-hint">${matchingContract?'Puxado do contrato. Pode ser alterado manualmente.':'Informe a data prevista para entrega/assinatura das chaves.'}</small></label></div><div class="form-grid"><label>Vistoriador (opcional)<select name="inspector_id"><option value="">Definir depois</option>${inspectors.map(u=>`<option value="${h(u.id)}" ${values.inspector_id===u.id?'selected':''}>${h(u.name)}</option>`).join('')}</select>${inspectors.length?'':'<small class="field-hint">Defina o cargo Vistoriador na equipe para atribuir um horário.</small>'}</label><label>Data e horário propostos<input type="datetime-local" name="scheduled_at" value="${h(values.scheduled_at)}"><small class="field-hint">Opcional. A duração será ajustada pelo vistoriador.</small></label></div>`,'inspection','Criar pedido');
}
