function newOrder(){if(!state.providers.length){toast('Cadastre um prestador primeiro.',true);return;}const approved=detail.quotes.filter(q=>q.status==='approved');editor('Agendar ordem de serviço',`<label>Tipo<select name="kind"><option value="diagnosis">Visita diagnóstica</option><option value="execution" ${approved.length?'':'disabled'}>Execução do reparo</option><option value="return" ${approved.length?'':'disabled'}>Retorno com orçamento aprovado</option></select></label><p class="small-text muted">Diagnóstico pode vir antes da proposta. Reparo exige orçamento aprovado e escopo correspondente.</p><label>Orçamento aprovado<select name="quote_id"><option value="">Sem orçamento — diagnóstico</option>${approved.map(q=>`<option value="${h(q.id)}">Versão ${q.version} · ${money(q.total)}</option>`).join('')}</select></label><label>Prestador<select name="provider_id">${providerOptions()}</select></label><label>Escopo autorizado<textarea name="scope" rows="3" required maxlength="3000"></textarea></label><div class="form-grid"><label>Data e horário<input type="datetime-local" name="scheduled_at" required></label><label>Custo autorizado (R$)<input name="authorized_value" type="number" min="0" max="1000000" step="0.01" value="0" required></label></div><label>Quem autorizou?<input name="authorization_by" required maxlength="150"></label><label>Canal / referência da autorização<textarea name="authorization_note" rows="3" required maxlength="2000" placeholder="Registre a autorização específica para esta visita ou execução."></textarea></label>`,'order','Agendar OS');}
function updateOrder(id){editor('Atualizar execução',`<input type="hidden" name="order_id" value="${h(id)}"><label>Situação<select name="status"><option value="completed">Concluída</option><option value="in_progress">Em execução</option><option value="cancelled">Cancelada</option></select></label><label>O que foi realizado / motivo<textarea name="completion" rows="4" maxlength="4000"></textarea></label><label>Evidência ou justificativa sem foto<textarea name="evidence_note" rows="3" maxlength="2000" placeholder="Referencie o anexo ou explique por que não há imagem."></textarea></label>`,'order-update','Salvar execução');}
function newCost(){editor('Registrar despesa',`<p class="form-intro">O registro não gera cobrança de aluguel nem transferência.</p><label>Descrição<input name="description" required maxlength="250"></label><div class="form-grid"><label>Valor realizado (R$)<input name="value" type="number" min="0.01" max="1000000" step="0.01" required></label><label>Vencimento<input type="date" name="due_date" value="${today()}" required></label></div><label>Responsável pelo pagamento<select name="payer"><option>Proprietário</option><option>Inquilino</option><option>Imobiliária</option><option>Outro</option></select></label>`,'cost','Registrar despesa');}
function payCost(id){const c=detail.costs.find(c=>c.id===id);editor('Registrar pagamento externo',`<input type="hidden" name="cost_id" value="${h(id)}"><p class="form-intro">Saldo de ${money(c.amount-c.paid)}. Registre um pagamento já feito fora do sistema.</p><label>Valor pago (R$)<input name="value" type="number" min="0.01" max="${(c.amount-c.paid)/100}" step="0.01" value="${((c.amount-c.paid)/100).toFixed(2)}" required></label><label>Referência / comprovante<textarea name="note" rows="4" required maxlength="2000"></textarea></label>`,'payment','Registrar pagamento');}
function newAttachment(){editor('Anexar foto ou documento',`<p class="form-intro">JPEG, PNG, WebP ou PDF, até 5 MB. Acesso restrito à equipe.</p><label>Arquivo<input name="file" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" required></label>`,'attachment','Enviar anexo');}
function syncOrderFields(){const form=$('#editor form');if(form?.dataset.form!=='order')return;const kind=form.elements.kind.value;const q=detail.quotes.find(q=>q.id===form.elements.quote_id.value&&q.status==='approved');if(kind!=='diagnosis'&&q){form.elements.provider_id.value=q.provider_id;form.elements.scope.value=q.scope;form.elements.authorized_value.value=(q.total/100).toFixed(2);}form.elements.scope.readOnly=kind!=='diagnosis';form.elements.authorized_value.readOnly=kind!=='diagnosis';}
async function afterDetail(updated,message){detail=updated;await load();renderDetail();$('#editor').close();toast(message);}

function userEditor(user=null){
  if(!canManage()){toast('Apenas a Gestão pode administrar usuários.',true);return;}
  const isNew=!user,defaultRole=user?.role||'staff',roleOptions=Object.entries(userRoleNames).map(([role,label])=>`<option value="${role}" ${defaultRole===role?'selected':''}>${label}</option>`).join('');
  editor(isNew?'Adicionar usuário':'Editar acesso',`<p class="form-intro">Defina o cargo e os acessos desta pessoa.</p><label>Nome completo<input name="name" required maxlength="150" value="${h(user?.name||'')}" autocomplete="name"></label><div class="form-grid"><label>Nome de usuário<input name="username" required maxlength="64" pattern="[a-zA-Z0-9][a-zA-Z0-9._-]{1,63}" value="${h(user?.username||'')}" placeholder="Ex.: maria_silva" autocomplete="username"></label><label>E-mail (opcional)<input name="email" type="email" maxlength="180" value="${h(user?.email||'')}" placeholder="nome@imobiliaria.com" autocomplete="email"></label></div><label>Cargo / nomenclatura<select name="job_title">${options(userTitleNames,user?.job_title||'')}</select><small class="field-hint">Gestora, Gerente, Atendente, Assistente ou Vistoriador. O cargo não altera as permissões.</small></label><label>Acesso ao painel<select name="role" required>${roleOptions}</select><small class="field-hint">Gestão administra a equipe; Atendimento cuida das vistorias e chamados; Financeiro acessa custos e pagamentos.</small></label><label>${isNew?'Senha inicial':'Nova senha (opcional)'}<input name="password" type="password" ${isNew?'required':''} minlength="4" maxlength="200" autocomplete="new-password" placeholder="${isNew?'Mínimo de 4 caracteres':'Deixe em branco para manter'}"></label>${isNew?'<small class="field-hint">Se não informar e-mail, será gerado um endereço interno de sistema.</small>':`<label>Situação<select name="active"><option value="1" ${user.active?'selected':''}>Ativo</option><option value="0" ${!user.active?'selected':''}>Inativo</option></select><small class="field-hint">Inativar bloqueia o login e preserva o histórico.</small></label>`}`,'user','Salvar usuário');
  $('#editor form').dataset.id=user?.id||'';
}
document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action],[data-nav],[data-ticket],[data-inspection],[data-contract]');if(!el)return;
  try {
    if(el.dataset.nav){event.preventDefault();navigate(el.dataset.nav);return;}
    if(el.dataset.inspection){await openInspection(el.dataset.inspection);return;}
    if(el.dataset.contract){await openContract(el.dataset.contract);return;}
    if(el.dataset.ticket){await openTicket(el.dataset.ticket);return;}
    const a=el.dataset.action;
    if(a==='logout'){await post('/logout',{});state=null;login();}
    if(a==='new-ticket')newTicket();if(a==='new-inspection')newInspection();if(a==='new-contract')newContract();if(a==='new-property')newProperty();if(a==='new-provider')newProvider();
    if(a==='edit-provider'){const p=state.providers.find(x=>x.id===el.dataset.id);if(p)providerEditor(p);return;}
    if(a==='delete-provider'){
      const p=state.providers.find(x=>x.id===el.dataset.id);if(!p)return;
      const ok=await confirmModal({
        title:'Excluir prestador',
        message:`Deseja excluir o cadastro de ${p.name}?`,
        detailText:'Caso o prestador já possua ordens de serviço ou orçamentos registrados no histórico, você poderá inativá-lo para preservar os registros.',
        confirmText:'Excluir prestador',
        cancelText:'Cancelar',
        danger:true
      });
      if(!ok)return;
      try{
        await api(`/providers/${p.id}`,{method:'DELETE'});
        await load();toast(`Prestador ${p.name} excluído com sucesso.`);
      }catch(err){toast(err.message,true);}
      return;
    }
    if(a==='new-user')userEditor();if(a==='edit-user'){const user=state.adminUsers?.find(u=>u.id===el.dataset.id);if(user)userEditor(user);}
    if(a==='inspection-add-property'){pendingInspectionDraft=Object.fromEntries(new FormData($('#editor form[data-form="inspection"]')));newProperty();}
    if(a==='contract-add-property'){pendingContractDraft=Object.fromEntries(new FormData($('#editor form[data-form="contract"]')));newProperty();}
    if(a==='close-editor'){if(pendingInspectionDraft){const draft=pendingInspectionDraft;pendingInspectionDraft=null;newInspection(draft);}else if(pendingContractDraft){const draft=pendingContractDraft;pendingContractDraft=null;newContract(draft);}else $('#editor').close();}if(a==='close-details')$('#details').close();
    if(a==='theme'){theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem(themeKey,theme);el.setAttribute('aria-label',`Ativar tema ${theme==='dark'?'claro':'escuro'}`);el.title=`Ativar tema ${theme==='dark'?'claro':'escuro'}`;el.innerHTML=icon(theme==='dark'?'sun':'moon');}
    if(a==='inspection-view'){inspectionView=el.dataset.view;$('#page-content').innerHTML=content();}
    if(a==='open-notification'){
      const notification=state.notifications.items.find(n=>n.id===el.dataset.id);
      if(notification){if(!notification.read_at)await post(`/notifications/${notification.id}/read`,{});await load();if(notification.type==='contract'){navigate('contracts');await openContract(notification.contract_id);}else{navigate('inspections');await openInspection(notification.inspection_id);}}
    }
    if(a==='start-contract'||a==='send-contract-manager'){
      const c=contractDetail,action=a==='start-contract'?'start':'send_to_manager';
      await api(`/contracts/${c.id}`,{method:'PATCH',body:JSON.stringify({revision:c.revision,action})});
      await load();await openContract(c.id);toast(action==='start'?'Confecção iniciada.':'Contrato enviado à gestora.');
    }
    if(a==='justify-contract-delay')contractDelayEditor();
    if(a==='accept-inspection'||a==='decline-inspection'){
      const i=inspectionDetail,accept=a==='accept-inspection';
      await api('/inspections/'+i.id,{method:'PATCH',body:JSON.stringify({revision:i.revision,status:accept?'received':'new',inspector_id:accept?i.inspector_id:'',scheduled_at:accept?i.scheduled_at:'',duration_minutes:accept?i.duration_minutes:0,reason:accept?'':'Horário recusado pelo vistoriador.',completion_note:i.completion_note})});
      await load();await openInspection(i.id);toast(accept?'Horário aceito.':'Horário liberado para novo agendamento.');
    }
    if(a==='clear-inspection-filters')navigate('inspections');
    if(a==='reset-inspection'){
      const ok = await confirmModal({
        title: 'Remover acompanhamento',
        message: 'Deseja apagar o que foi adicionado neste acompanhamento?',
        detailText: 'O agendamento, vistoriador e notas serão removidos. A vistoria voltará ao estado "Nova" e ficará pronta para você preencher novamente.',
        confirmText: 'Apagar e liberar preenchimento',
        cancelText: 'Cancelar',
        danger: true
      });
      if(!ok) return;
      const updated=await post(`/inspections/${el.dataset.id}/reset`,{});
      inspectionDetail=updated;await load();renderInspectionDetail();toast('Acompanhamento limpo. Vistoria liberada para preencher novamente.');return;
    }
    if(a==='delete-ticket'){
      const protocol=el.dataset.protocol||'esta solicitação de manutenção';
      const ok = await confirmModal({
        title: 'Excluir solicitação de manutenção',
        message: `Deseja excluir permanentemente ${protocol}?`,
        detailText: 'Todos os orçamentos, ordens de serviço, notas e registros desta solicitação de manutenção serão apagados definitivamente do sistema.',
        confirmText: 'Excluir definitivamente',
        cancelText: 'Cancelar',
        danger: true
      });
      if(!ok) return;
      await api(`/tickets/${el.dataset.id}`,{method:'DELETE'});
      $('#details').close();detail=null;await load();navigate('tickets');toast(`${protocol} excluída com sucesso.`);return;
    }
    if(a==='delete-inspection'){
      const protocol=el.dataset.protocol||'esta vistoria';
      const ok = await confirmModal({
        title: 'Excluir vistoria',
        message: `Deseja excluir permanentemente ${protocol}?`,
        detailText: 'Esta vistoria e todo o histórico do pedido serão removidos definitivamente.',
        confirmText: 'Excluir vistoria',
        cancelText: 'Cancelar',
        danger: true
      });
      if(!ok) return;
      await api(`/inspections/${el.dataset.id}`,{method:'DELETE'});
      $('#details').close();inspectionDetail=null;await load();navigate('inspections');toast(`${protocol} excluída com sucesso.`);return;
    }
    if(a==='open-linked-contract'){await openContract(el.dataset.id);return;}
    if(a==='open-linked-inspection'){await openInspection(el.dataset.id);return;}
    if(a==='quick-contract-for-inspection'){pendingInspectionDraft=Object.fromEntries(new FormData($('#editor form[data-form="inspection"]')));newContract({property_id:el.dataset.property,kind:'occupation'});return;}
    if(a==='calendar-month'){const d=new Date(`${inspectionMonth}-01T12:00:00`);d.setMonth(d.getMonth()+Number(el.dataset.step));inspectionMonth=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;$('#page-content').innerHTML=content();}
    if(a==='detail-tab'){detailTab=el.dataset.tab;renderDetail();}
    if(a==='metric'){const f=el.dataset.filter;if(['agenda','reports'].includes(f))navigate(f);else navigate('tickets',f==='all'?{}:{[f]:true});}
    if(a==='ticket-tab')navigate('tickets',el.dataset.filter==='all'?{}:{[el.dataset.filter]:true});
    if(a==='clear-filters')navigate('tickets');
    if(a==='property-tickets')navigate('tickets',{property:el.dataset.id});
    if(a==='provider-agenda')navigate('agenda',{provider:el.dataset.id});
    if(a==='new-quote')newQuote();if(a==='decide-quote')decideQuote(el.dataset.id);
    if(a==='new-order')newOrder();if(a==='update-order')updateOrder(el.dataset.id);
    if(a==='new-cost')newCost();if(a==='pay-cost')payCost(el.dataset.id);if(a==='attachment')newAttachment();
    if(a==='add-quote-item')$('#quote-items').insertAdjacentHTML('beforeend',quoteItem());
    if(a==='remove-quote-item')el.closest('.quote-item').remove();
  }catch(e){toast(e.message,true);}
});
document.addEventListener('change',e=>{
  if(e.target.matches('[data-filter]')){filters[e.target.dataset.filter]=e.target.value;$('#page-content').innerHTML=content();}
  if(e.target.name==='property_id'&&e.target.closest('form')?.dataset.form==='ticket'){const p=state.properties.find(p=>p.id===e.target.value),f=e.target.form;f.elements.requester.value=p.tenant;f.elements.contact.value=p.contact;}
  if(['property_id','kind','requester_id'].includes(e.target.name)&&e.target.closest('form')?.dataset.form==='inspection'){const f=e.target.form;syncInspectionContract(f);}
  if(e.target.name==='kind'&&e.target.closest('form')?.dataset.form==='contract'){const input=e.target.form.elements.manual_reason,label=$('#contract-reason-label'),show=e.target.value==='other';label.hidden=!show;input.disabled=!show;input.required=show;}
  if(['kind','quote_id'].includes(e.target.name)&&e.target.closest('form')?.dataset.form==='order')syncOrderFields();
});
document.addEventListener('input',e=>{if(e.target.name==='deadline_at'&&e.target.closest('form')?.dataset.form==='inspection')delete e.target.dataset.auto;if(e.target.name==='duration_minutes'&&e.target.closest('form')?.dataset.form==='inspection')e.target.dataset.manual='1';if(e.target.dataset.filter==='q'){filters.q=e.target.value;const rows=filtered();$('#ticket-results').innerHTML=rows.length?table(rows):empty('Nenhum chamado encontrado','Tente buscar outro endereço, titular ou protocolo.');$('.result-count').textContent=`${rows.length} resultado${rows.length===1?'':'s'}`;}});
document.addEventListener('submit',async event=>{
  const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const submit=form.querySelector('[type=submit]');if(submit.disabled)return;
  const err=form.querySelector('.form-error');if(err)err.textContent='';submit.disabled=true;
  const values=Object.fromEntries(new FormData(form)),kind=form.dataset.form;
  try {
    if(kind==='login'){await post('/login',values);await load();return;}
    if(kind==='ticket'){const t=await post('/tickets',values);$('#editor').close();await load();await openTicket(t.id);toast(`${t.protocol} criado.`);return;}
    if(kind==='inspection'){const i=await post('/inspections',values);$('#editor').close();await load();navigate('inspections');await openInspection(i.id);toast(`${i.protocol} criado.`);return;}
    if(kind==='contract'){const c=await post('/contracts',values);$('#editor').close();await load();navigate('contracts');await openContract(c.id);toast('Solicitação de contrato criada.');return;}
    if(kind==='contract-delay'){const c=contractDetail;await api(`/contracts/${c.id}`,{method:'PATCH',body:JSON.stringify({revision:c.revision,action:'justify_delay',reason:values.reason})});$('#editor').close();await load();await openContract(c.id);toast('Justificativa registrada.');return;}
    if(kind==='inspection-update'){const updated=await api('/inspections/'+inspectionDetail.id,{method:'PATCH',body:JSON.stringify({...values,revision:inspectionDetail.revision})});$('#details').close();inspectionDetail=null;await load();toast('Vistoria atualizada.');return;}
    if(kind==='provider'){
      const id=form.dataset.id;
      if(id){
        await api('/providers/'+id,{method:'PATCH',body:JSON.stringify(values)});
      }else{
        await post('/providers',values);
      }
      $('#editor').close();await load();toast(id?'Prestador atualizado com sucesso.':'Prestador cadastrado com sucesso.');return;
    }
    if(kind==='property'){
      await post('/properties',values);
      const inspectionDraft=pendingInspectionDraft,contractDraft=pendingContractDraft;
      pendingInspectionDraft=null;pendingContractDraft=null;
      $('#editor').close();await load();
      if(inspectionDraft){const property=state.properties.find(p=>p.code===String(values.code).trim());if(property){newInspection({...inspectionDraft,property_id:property.id});toast('Imóvel cadastrado. Continue o pedido de vistoria.');return;}}
      if(contractDraft){const property=state.properties.find(p=>p.code===String(values.code).trim());if(property){newContract({...contractDraft,property_id:property.id});toast('Imóvel cadastrado. Continue a solicitação do contrato.');return;}}
      toast('Cadastro salvo.');return;
    }
    if(kind==='user'){
      const id=form.dataset.id,selfReset=id===state.user.id&&Boolean(values.password);
      await api(id?'/users/'+id:'/users',{method:id?'PATCH':'POST',body:JSON.stringify(values)});
      $('#editor').close();
      if(selfReset){state=null;login();toast('Senha alterada. Entre novamente com a nova senha.');return;}
      await load();toast(id?'Acesso atualizado.':'Usuário criado.');return;
    }
    let updated;
    const base='/tickets/'+detail.id;
    if(kind==='triage')updated=await api(base,{method:'PATCH',body:JSON.stringify({...values,revision:detail.revision})});
    if(kind==='note')updated=await post(base+'/notes',values);
    if(kind==='quote'){values.items=[...form.querySelectorAll('.quote-item')].map(row=>({label:row.querySelector('[name=item_label]').value,cents:Math.round(Number(row.querySelector('[name=item_value]').value)*100)}));updated=await post(base+'/quotes',values);}
    if(kind==='decision')updated=await post(base+'/quotes/'+values.quote_id,values);
    if(kind==='order')updated=await post(base+'/orders',{...values,authorized_cents:Math.round(Number(values.authorized_value)*100)});
    if(kind==='order-update')updated=await post(base+'/orders/'+values.order_id,values);
    if(kind==='cost')updated=await post(base+'/costs',{...values,amount:Math.round(Number(values.value)*100)});
    if(kind==='payment')updated=await post(base+'/costs/'+values.cost_id,{...values,amount:Math.round(Number(values.value)*100)});
    if(kind==='attachment'){
      const file=form.elements.file.files[0];if(!file)throw new Error('Escolha um arquivo.');if(file.size>5*1024*1024)throw new Error('Use um arquivo de até 5 MB.');
      const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Não foi possível ler o arquivo.'));reader.readAsDataURL(file);});
      updated=await post(base+'/attachments',{name:file.name,mime:file.type,data});
    }
    if(updated)await afterDetail(updated,'Registro salvo.');
  }catch(e){if(err)err.textContent=e.message;else toast(e.message,true);}finally{submit.disabled=false;}
});
window.addEventListener('hashchange',()=>{if(state)navigate(location.hash.slice(1));});
for(const id of ['editor','details'])$('#'+id).addEventListener('click',event=>{if(event.target===$('#'+id)){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
$('#editor').addEventListener('close',()=>{if(pendingInspectionDraft){const draft=pendingInspectionDraft;pendingInspectionDraft=null;newInspection(draft);}else if(pendingContractDraft){const draft=pendingContractDraft;pendingContractDraft=null;newContract(draft);}});
try{await load();}catch(error){if(!state)login();else toast(error.message,true);}
setInterval(()=>{if(state)refreshNotifications().catch(()=>{});},30000);
